NAME = 'ACV: A Conservative Version'
BOOK = 'Mark'

CHAPTERS = {
    1: {
        1: 'Začetek evangelija Jezusa Kristusa, Sina Božjega.',
        2: 'Kakor je pisano v proroku Izaiju: „Glej, pošiljam angela svojega pred obličjem tvojim, ki pripravi pot tvojo.',
        3: 'Glas vpijočega v puščavi: Pripravite pot Gospodov, poravnajte steze njegove“,',
        4: 'tako je nastopil Janez Krstnik v puščavi, oznanjujoč krst izpokorjenja v odpuščenje grehov.',
        5: 'In k njemu je prihajala vsa Judejska dežela in vsi Jeruzalemci, in krstil jih je v reki Jordanu, pripoznavajoče grehe svoje.',
        6: 'Bil je pa Janez oblečen v velblodjo dlako in usnjen pas je imel okoli ledja svojega, in jedel je kobilice in divji med.',
        7: 'In propovedoval je, govoreč: Močnejši od mene gre za menoj, kateremu nisem vreden, sklonivši se, odvezati jermenov na obuvalu njegovem.',
        8: 'Jaz sem vas krstil z vodo, ali on vas bo krstil s svetim Duhom.',
        9: 'In zgodi se tiste dni, da pride Jezus iz Nazareta v Galileji, in Janez ga krsti v Jordanu.',
        10: 'In precej, ko stopi iz vode, zagleda, da se odpirajo nebesa, in Duh kakor golob gre navzdol nanj.',
        11: 'In glas se začuje iz nebes: Ti si Sin moj ljubljeni, ti si po moji volji.',
        12: 'In precej ga odvede Duh v puščavo.',
        13: 'In v puščavi je bil štirideset dni, in satan ga je izkušal, in bival je med zvermi; in angeli so mu stregli.',
        14: 'Ko so pa Janeza izročili Herodu, pride Jezus v Galilejo, oznanjujoč evangelij Božji',
        15: 'in govoreč: Čas je dopolnjen in Božje kraljestvo se je približalo. Izpokorite se in verujte v evangelij!',
        16: 'Hodeč ob Galilejskem morju, pa ugleda Simona in Andreja, njegovega brata, da mečeta mreže v morje; bila sta namreč ribiča.',
        17: 'In reče jima Jezus: Pojdita za menoj, in naredim, da postaneta lovca ljudi.',
        18: 'In popustita precej mreže svoje ter gresta za njim.',
        19: 'In prišedši malo dalje, ugleda Jakoba, sina Zebedejevega, in njegovega brata Janeza; tudi ona popravljata v ladji mreže.',
        20: 'In precej ju pokliče, in popustita svojega očeta Zebedeja v ladji z najemniki in odideta za njim.',
        21: 'In pridejo v Kafarnavm; in precej v soboto gre v shodnico in uči.',
        22: 'In oni ostrme ob nauku njegovem, kajti uči jih, kakor kdor ima oblast in ne kakor pismarji.',
        23: 'In precej se pokaže, da je v njih shodnici človek, ki ima nečistega duha;',
        24: 'ta zavpije, rekoč: Kaj imaš z nami, Jezus Nazareški? Prišel si, da nas pogubiš? Poznam te, kdo si: Svetnik Božji.',
        25: 'In zapreti mu Jezus, rekoč: Umolkni in izidi iz njega.',
        26: 'In nečisti duh ga strese in zakriči z močnim glasom ter izide iz njega.',
        27: 'In vsi se prestrašijo, tako da vprašujejo drug drugega, govoreč: Kaj je to? Kakšen nov nauk! Z oblastjo ukazuje tudi nečistim duhovom, pa so mu pokorni.',
        28: 'In precej se raznese glas o njem povsod po vsej Galilejski pokrajini.',
        29: 'In precej gredo iz shodnice in pridejo v hišo Simonovo in Andrejevo z Jakobom in Janezom vred.',
        30: 'Tašča Simonova pa je ležala mrzlična, in precej mu povedo o njej.',
        31: 'In pristopi, jo prime za roko ter vzdigne, in mrzlica jo pusti, in ona jim je stregla.',
        32: 'Zvečer pa, ko je solnce zatonilo, so prinašali k njemu vse bolnike in obsedence.',
        33: 'In vse mesto je bilo zbrano pri vratih.',
        34: 'In ozdravil je mnogo bolnikov različnih bolezni in zlih duhov je mnogo izgnal ter ni dovolil govoriti zlim duhovom, ker so ga poznali.',
        35: 'In zjutraj, ko je še tema bila, vstane in gre ven ter odide na samoten kraj in tam moli.',
        36: 'In za njim pohiti Simon in kateri so bili ž njim,',
        37: 'in ko ga najdejo, mu reko: Vsi te iščejo.',
        38: 'In jim reče: Pojdimo drugam, v bližnje trge, da bom tudi tam propovedoval, kajti zato sem prišel.',
        39: 'Ter gre in propoveduje v njih shodnicah po vsej Galileji in izganja zle duhove.',
        40: 'In pride k njemu gobavec, ga klečé prosi in mu reče: Če hočeš, me moreš očistiti.',
        41: 'In Jezus, ganjen usmiljenja, iztegne roko svojo in se ga dotakne ter mu reče: Hočem, bodi očiščen!',
        42: 'In mu precej preide goba in bil je čist.',
        43: 'In ostro mu zapretivši, ga precej odpošlje',
        44: 'in mu veli: Glej, da nikomur nič ne poveš, temuč pojdi, pokaži se duhovnikom in daruj za očiščenje svoje, kar je ukazal Mojzes, njim v pričevanje.',
        45: 'On pa, ko izide, začne z vnemo oznanjevati in razglašati reč, tako da ni mogel Jezus nič več očitno priti v mesto, ampak je bival zunaj po samotnih krajih; in prihajali so k njemu od vseh strani.',
    },
    2: {
        1: 'In ko pride čez nekoliko dni zopet v Kafarnavm, začujejo, da je doma.',
        2: 'In precej se jih zbere mnogo, toliko, da niso imeli prostora tudi pred vrati ne. In govoril jim je besedo Božjo.',
        3: 'Pa pridejo in prineso k njemu mrtvoudnega, ki so ga štirje nosili.',
        4: 'In ko se mu niso mogli približati zavoljo množice, odkrijejo streho, kjer je bil; in ko so jo predrli, spuste doli posteljo, na kateri je mrtvoudni ležal.',
        5: 'Ko pa vidi Jezus njih vero, reče mrtvoudnemu: Sin, odpuščeni so ti grehi.',
        6: 'Tam pa je sedelo nekaj pismarjev, ki so premišljali v srcih svojih:',
        7: 'Kaj ta tako govori? Boga preklinja! Kdo more odpuščati grehe, razen eden, Bog?',
        8: 'In spoznavši precej z duhom svojim, da tako premišljajo sami pri sebi, jim reče Jezus: Kaj to premišljate v srcih svojih?',
        9: 'Kaj je laže, reči mrtvoudnemu: Odpuščeni so ti grehi, ali reči: Vstani in vzemi posteljo svojo in hodi?',
        10: 'Da boste pa vedeli, da ima Sin človekov oblast, na zemlji odpuščati grehe (veli mrtvoudnemu):',
        11: 'Tebi pravim: Vstani, vzemi posteljo svojo in pojdi na dom svoj!',
        12: 'In vstane in precej vzame posteljo ter odide vpričo vseh, da se vsi čudijo in Boga hvalijo, govoreč: Nikoli nismo kaj takega videli!',
        13: 'In zopet odide k morju. In vse ljudstvo je prihajalo k njemu, in jih je učil.',
        14: 'In mimogrede ugleda Levija, sina Alfejevega, sedečega na mitnici, in mu reče: Pojdi za menoj! In vstane in gre za njim.',
        15: 'In zgodi se, ko je sedel za mizo v hiši njegovi, da je tudi mnogo cestninarjev in grešnikov sedelo z Jezusom in njegovimi učenci; kajti veliko jih je bilo, in so hodili za njim.',
        16: 'In ko pismarji in farizeji vidijo, da jé s cestninarji in grešniki, reko učencem njegovim: Z mitarji in grešniki jé in pije!',
        17: 'In ko Jezus to sliši, jim reče: Zdravi ne potrebujejo zdravnika, ampak bolni. Nisem prišel klicat pravičnih, ampak grešnike.',
        18: 'Učenci Janezovi in farizeji pa so se postili; ter pridejo in mu reko: Zakaj se Janezovi in farizejski učenci postijo, tvoji učenci se pa ne postijo?',
        19: 'In Jezus jim reče: Ali se morejo svatje postiti, kadar je ženin ž njimi? Dokler imajo s seboj ženina, se ne morejo postiti.',
        20: 'Pridejo pa dnevi, ko se jim odvzame ženin; in tedaj se bodo postili tisti dan.',
        21: 'Nihče ne prišiva zaplate iz novega sukna na staro oblačilo, sicer odtrga nova zaplata še kaj od starega in luknja se naredi še hujša.',
        22: 'In nihče ne deva novega vina v stare mehove, sicer predere novo vino mehove, in vino pride v nič in tudi mehovi; temuč novo vino je vlivati v nove mehove.',
        23: 'In zgodi se, da je šel v soboto skozi setve, in učenci njegovi začno po poti grede trgati klasje.',
        24: 'Pa mu reko farizeji: Glej, kaj delajo v soboto, kar se ne sme?',
        25: 'In jim reče: Niste li nikoli brali, kaj je storil David, ko je bil v sili in lačen, on in kateri so bili ž njim?',
        26: 'Kako je šel v hišo Božjo, ko je bil Abiatar veliki duhovnik, in je jedel predložene kruhe, ki jih ne sme nihče jesti razen duhovnikov, in je dal tudi tistim, ki so bili ž njim?',
        27: 'In jim reče: Sobota je ustvarjena zaradi človeka, a ne človek zaradi sobote.',
        28: 'Zato je Sin človekov tudi sobote gospodar.',
    },
    3: {
        1: 'In zopet pride v shodnico, in tam je bil človek, ki je imel usehlo roko.',
        2: 'In pazili so nanj, če ga ozdravi v soboto, da bi ga zatožili.',
        3: 'In reče človeku, ki je imel suho roko: Stopi na sredo!',
        4: 'In jim reče: Ali se sme v soboto storiti dobro ali hudo? življenje oteti ali pogubiti? Oni pa molčijo.',
        5: 'In jih z jezo pogleda naokrog, pomilujoč zakrknjenost njih srca, in veli človeku: Iztegni roko svojo! In iztegne, in roka njegova je bila zdrava.',
        6: 'In farizeji izidejo in se precej s Herodovci posvetujejo zoper njega, kako bi ga pogubili.',
        7: 'A Jezus se umakne z učenci svojimi k morju; in velika množica iz Galileje je šla za njim; tudi iz Judeje',
        8: 'in iz Jeruzalema in iz Idumeje in z one strani Jordana in od Tira in Sidona, velika množica, ko so slišali, kakšne reči dela, so prišli k njemu.',
        9: 'In reče učencem svojim, naj mu bode ladjica pripravljena zavoljo množice, da ga ne bi stiskali.',
        10: 'Kajti mnogo jih je bil ozdravil, zato so se rinili k njemu, da bi se ga doteknili, katerikoli so imeli nadloge.',
        11: 'In kadar so ga nečisti duhovi videli, so padali pred njim in kričali, govoreč: Ti si Sin Božji.',
        12: 'In zelo jim je pretil, naj ga ne razglašajo.',
        13: 'In stopi na goro in pokliče k sebi, katere je sam hotel; in pridejo k njemu.',
        14: 'In postavi jih dvanajst, da bodo ž njim in da jih pošlje propovedovat',
        15: 'ter da imajo oblast izganjati zle duhove:',
        16: 'Simona, in mu dá ime Peter,',
        17: 'in Jakoba, sina Zebedejevega, in Janeza, brata Jakobovega, in da jima ime Boanerges, to je: sinova groma,',
        18: 'in Andreja in Filipa in Jerneja in Matevža in Tomaža in Jakoba, sina Alfejevega, in Tadeja in Simona Kananejca',
        19: 'in Juda Iškariota, ki ga je tudi izdal.',
        20: 'In pridejo v hišo. In zopet se zbere množica, tako da še kruha niso mogli jesti.',
        21: 'In ko to slišijo sorodniki njegovi, se napotijo, da bi ga prijeli; pravijo namreč: Ni sam ob sebi.',
        22: 'In pismarji, ki so bili prišli iz Jeruzalema, pravijo: Belzebuba ima, in: S poglavarjem hudičev izganja zle duhove.',
        23: 'In jih pokliče k sebi in jim govori v prilikah: Kako more satan satana izganjati?',
        24: 'In če se kraljestvo razdvoji samo zoper sebe, ne more obstati to kraljestvo.',
        25: 'In če se dom razdvoji sam zoper sebe, ne bo mogel obstati ta dom.',
        26: 'In če je vstal satan sam zoper sebe in se je razdvojil, ne more obstati, temuč konec ga je.',
        27: 'Nasprotno ne more iti nihče v hišo močnemu in mu pobrati pohištva, če poprej ne zveže močnega, in potem šele opleni hišo njegovo.',
        28: 'Resnično vam pravim, da se vsi grehi odpuste sinovom človeškim, tudi kletvine, s katerimikoli bi prekleli Boga;',
        29: 'kdor pa prekolne svetega Duha, nima odpuščenja na vekomaj, temuč je kriv večnega greha.',
        30: 'Kajti govorili so: Nečistega duha ima.',
        31: 'In pridejo bratje njegovi in mati njegova in stoječ zunaj, pošljejo k njemu, da ga pokličejo.',
        32: 'In ljudstvo sedi okoli njega, in mu reko: Glej, mati tvoja in bratje tvoji zunaj vprašujejo po tebi.',
        33: 'In odgovori jim, rekoč: Kdo je mati moja ali bratje moji?',
        34: 'In ozre se okrog po tistih, ki so sedeli okoli njega, in reče: Glej, mati moja in bratje moji!',
        35: 'Kdorkoli stori voljo Božjo, ta je brat moj in sestra moja in mati.',
    },
    4: {
        1: 'In zopet začne učiti ob morju. In zbere se pri njem tako velika množica, da mora stopiti v ladjo in sedeti v njej na morju; in vsa množica se razpostavi kraj morja po tleh.',
        2: 'In mnogo jih je učil v prilikah in jim pravil v poučevanju svojem:',
        3: 'Poslušajte! Glej, sejalec gre sejat.',
        4: 'In zgodi se, ko seje, da pade nekaj zrnja poleg ceste, in prilete ptice in ga pozobljejo.',
        5: 'A drugo pade na skalnata tla, kjer nima veliko prsti, in precej požene, ker nima globoke zemlje.',
        6: 'Ko pa vzide solnce, uvene, in ker nima korenine, usahne.',
        7: 'In drugo pade v trnje, in trnje vzraste in ga uduši, in ne prinese sadu.',
        8: 'In drugo pade na dobro zemljo, in prinaša sad, ki raste in se množi in rodi po tridesetero in po šestdesetero in po stotero.',
        9: 'In reče: Kdor ima ušesa, da sliši, naj sliši!',
        10: 'In ko je bil sam, ga vprašajo tisti, ki so bili pri njem z dvanajsterimi, po prilikah.',
        11: 'In jim reče: Vam je dana skrivnost kraljestva Božjega, onim pa, ki so zunaj, se vse godi v prilikah,',
        12: 'da „gledajoč vidijo, pa ne spoznajo, ter poslušajoč slišijo, pa ne razumejo: da se ne bi kdaj izpreobrnili, in bilo bi jim odpuščeno“.',
        13: 'In jim reče: Ne umete li te prilike? In kako boste vse prilike umeli?',
        14: 'Sejalec seje besedo.',
        15: 'Ti so pa, ki so poleg ceste: kjer se seje beseda, in ko jo slišijo, precej pride satan in vzame besedo, ki je posejana vanje.',
        16: 'In enako so ti, pri katerih je posejano na skalnata tla: ko slišijo besedo, jo precej z veseljem sprejmo;',
        17: 'pa nimajo korenine v sebi, temuč so nestanovitni; ko potem nastane stiska ali preganjanje zaradi besede, se precej pohujšajo.',
        18: 'In drugi so, pri katerih je posejano v trnje: tisti, ki besedo slišijo,',
        19: 'pa skrbi tega sveta in slepilo bogastva in želje po drugih rečeh se prikradejo in zaduše besedo in ostane brez sadu.',
        20: 'In ti so, pri katerih je na dobro zemljo posejano: ki besedo poslušajo in sprejemajo ter prinašajo sad, trideseteren, šestdeseteren in stoteren.',
        21: 'In jim reče: Se li mar prinaša sveča, da se postavi pod mernik ali pod posteljo? A ne, da se postavi na svečnik?',
        22: 'Kajti nič ni skritega, kar se ne bi razodelo, in nič ni tako skrivnega, da ne bi prišlo na svetlo.',
        23: 'Če ima kdo ušesa, da sliši, naj sliši!',
        24: 'In jim reče: Pomislite, kaj slišite! S kakršno mero merite, se odmeri vam in še pridene se vam.',
        25: 'Kajti kdor ima, se mu bo dalo, a kdor nima, se mu odvzame tudi to, kar ima.',
        26: 'In reče: Tako je s kraljestvom Božjim, kakor če človek vrže seme v zemljo,',
        27: 'in spi in vstaja po noči in po dnevi, in seme poganja in raste, da on ne ve kako.',
        28: 'Zemlja sama od sebe rodi sad: najprej steblo, potem klas, potem polno pšenico v klasu.',
        29: 'Ko pa sad dozori, precej pošlje srp, kajti prišla je žetev.',
        30: 'In reče: S čim naj primerjamo kraljestvo Božje? ali v kakšni priliki naj ga upodobimo?',
        31: 'Ono je kakor gorčično zrno, ki je, ko se vseje v zemljo, manjše od vseh semen na zemlji,',
        32: 'a ko je vsejano, raste in postane večje od vseh zelišč, in poganja velike veje, da morejo ptice nebeške gnezditi pod senco njegovo.',
        33: 'In v mnogih takih prilikah jim je govoril besedo, v kolikor so jo mogli poslušati.',
        34: 'Brez prilike pa jim ni govoril, a na samem je učencem svojim razlagal vse.',
        35: 'In jim reče tisti dan, ko se je zvečerilo: Prepeljimo se na oni kraj.',
        36: 'In pusté množico ter ga vzemo s seboj, kakor je bil v ladji; tudi druge ladjice so bile ž njim.',
        37: 'Kar nastane velik vihar, in valovi so se zaganjali v ladjo, da se je že napolnjevala.',
        38: 'In on je bil na krmi, speč na blazini; in ga zbude in mu reko: Učenik, ali ti nič ni mar, da pogibljemo?',
        39: 'In prebudivši se, zapreti vetru in reče morju: Umolkni, pomiri se! In preneha veter, in nastane velika tihota.',
        40: 'In jim reče: Kaj ste tako plašni? ali še nimate vere?',
        41: 'In velik strah jih obide, in govore med seboj: Kdo vendar je ta, da sta mu celo veter in morje pokorna?',
    },
    5: {
        1: 'In pridejo na drugo stran morja, v pokrajino Gerazenov.',
        2: 'In precej, ko stopi iz ladje, ga sreča človek iz grobov, ki je imel nečistega duha',
        3: 'in mu je bilo prebivališče po grobih; in tudi z verigo ga ni mogel nihče več zvezati;',
        4: 'bil je namreč velikokrat zvezan z oklepi in verigami, pa je verige potrgal in oklepe razdrobil, in nihče ga ni mogel ukrotiti;',
        5: 'in vedno, po noči in po dnevi, je bival po gorah in po grobih ter kričal in se bil s kamenjem.',
        6: 'Ko pa ugleda Jezusa oddaleč, priteče ter se mu prikloni',
        7: 'in na ves glas kričeč, reče: Kaj imam s teboj, Jezus, Sin Boga Najvišjega? Zaklinjam te pri Bogu, ne muči me!',
        8: 'Pravil mu je namreč: Izidi, nečisti duh, iz tega človeka!',
        9: 'In ga vpraša: Kako ti je ime? In mu reče: Legijon mi je ime, ker nas je mnogo.',
        10: 'In prosi ga zelo, naj jih ne izžene iz tega kraja.',
        11: 'Bila je pa tam pri gori velika čreda svinj, ki so se pasle.',
        12: 'In zaprosijo ga, rekoč: Pošlji nas v te svinje, da gremo vanje.',
        13: 'In Jezus jim dovoli. In nečisti duhovi izidejo in gredo v svinje, in zakadi se čreda, kakih dvatisoč, z brega v morje, ter potonejo v morju.',
        14: 'In njih pastirji pobegnejo in oznanijo to v mestu in po deželi. In prebivalci gredo pogledat, kaj bi bilo to, kar se je zgodilo.',
        15: 'In pridejo k Jezusu in ugledajo obsedenca, da sedi in je oblečen in pameten, tistega, ki je imel legijon; in preplašijo se.',
        16: 'In tisti, ki so videli, jim pripovedujejo, kako se je zgodilo obsedencu, in o svinjah.',
        17: 'In začno ga prositi, naj odide iz njih krajev.',
        18: 'In ko stopi v ladjo, ga zaprosi oni, ki je bil obseden, da sme ostati ž njim.',
        19: 'Jezus pa mu ne dopusti, ampak mu reče: Pojdi na svoj dom k svojcem in oznani jim, koliko ti je storil Gospod in kako se te je usmilil.',
        20: 'In odide in začne oznanjevati po Deseteromestju, koliko mu je storil Jezus; in vsi so se čudili.',
        21: 'In ko se prepelje Jezus v ladji zopet na drugo stran, se zbere pri njem velika množica; in bil je pri morju.',
        22: 'In glej, eden načelnikov shodnice, po imenu Jair, pride, in ko ga ugleda, mu pade pred noge',
        23: 'in ga zelo prosi, rekoč: Hčerka mi umira, pridi, položi nanjo roke, da ozdravi in živi.',
        24: 'In odide ž njim; in velika množica ga spremlja in ga stiskajo.',
        25: 'In žena, ki je imela krvotok dvanajst let',
        26: 'in je veliko pretrpela od mnogih zdravnikov in potrošila vse svoje, pa ji ni nič pomagalo, ampak še huje je bilo:',
        27: 'pride, ko je slišala o Jezusu, med množico odzadaj in se dotakne obleke njegove.',
        28: 'Reče si namreč: Če se dotaknem le obleke njegove, ozdravim.',
        29: 'In precej usahne vir krvi njene, in čuti v telesu, da je ozdravela od svoje nadloge.',
        30: 'In Jezus precej spozna pri sebi, da je šla moč iz njega, in obrnivši se med množico, reče: Kdo se je dotaknil moje obleke?',
        31: 'In reko mu učenci njegovi: Saj vidiš ljudstvo, da te stiska, pa praviš: Kdo se me je dotaknil?',
        32: 'In ozira se okoli, da bi ugledal tisto, ki je to storila.',
        33: 'Žena pa, vedoč, kaj se ji je zgodilo, uplašena in trepetaje pristopi in pade pred njim in mu pove vso resnico.',
        34: 'On ji pa reče: Hči, vera tvoja te je rešila; pojdi v miru in bodi zdrava od nadloge svoje.',
        35: 'Ko še govori, pridejo od načelnika shodnice, rekoč: Hči tvoja je umrla, čemu še nadleguješ učenika?',
        36: 'Jezus pa zasliši to besedo, ko so jo povedali, in reče načelniku shodnice: Ne boj se, le veruj!',
        37: 'In ne pusti, da bi ga kdo spremljal, razen Peter in Jakob in Janez, Jakobov brat.',
        38: 'In pridejo v hišo načelnikovo, in vidi hrupno zmešnjavo ter da silno jokajo in žalujejo.',
        39: 'In ko vnide, jim reče: Kaj hrumite in jokate? Deklica ni umrla, marveč spi!',
        40: 'A oni se mu posmehujejo. On pa izžene vse in vzame s seboj otrokovega očeta in mater in svoje spremljevalce ter gre noter, kjer je deklica ležala.',
        41: 'In prijemši deklico za roko, ji veli: Talita kumi, to se pravi: Deklica, pravim ti, vstani!',
        42: 'In precej vstane deklica in hodi; imela je namreč dvanajst let. In precej se začudijo na vso moč.',
        43: 'In zapove jim strogo, da nihče ne zve tega, in naroči, naj ji dado jesti.',
    },
    6: {
        1: 'In gre odtod in pride v domovino svojo, in spremljajo ga učenci njegovi.',
        2: 'In ko pride sobota, začne učiti v shodnici; in mnogi poslušalci so strmeli, govoreč: Odkod temu to? in: Kakšna je ta modrost, ki mu je dana? in toliki čudeži se vrše po rokah njegovih!',
        3: 'Ali ni ta tesar, sin Marijin in brat Jakobov in Jozejev in Judov in Simonov? in niso li sestre njegove tu pri nas? In pohujševali so se nad njim.',
        4: 'Jezus jim pa reče: Nikjer ni prorok brez časti, razen v domovini svoji in pri rodbini svoji in na domu svojem.',
        5: 'In ni mogel ondi nobenega čudeža storiti, razen da je le malo bolnikov, položivši nanje roke, ozdravil.',
        6: 'In čudil se je njih neveri. In hodil je po vaseh v okolišu in učil.',
        7: 'In pokliče k sebi dvanajstere in jih začne razpošiljati po dva in dva, in da jim oblast nad nečistimi duhovi,',
        8: 'in zapove jim, naj ničesar ne jemljo na pot razen same palice: ne torbe, ne kruha, ne denarja v pasu,',
        9: 'ampak da naj si obujejo opanke, in veli: ne oblačite dveh sukenj.',
        10: 'In jim reče: Kjerkoli pridete v hišo, tam ostanite, dokler ne pojdete odondod naprej.',
        11: 'In v katerem mestu vas ne bi sprejeli in ne poslušali, odondod grede si otresite prah izpod nog njim v pričevanje.',
        12: 'In ko so odšli, so oznanjevali ljudem, naj se izpokore,',
        13: 'in so izganjali mnoge zle duhove in mazali z oljem mnoge bolnike in jih ozdravljali.',
        14: 'In kralj Herod zasliši o tem, kajti ime njegovo se je bilo razglasilo, in reče: Janez Krstnik je vstal iz mrtvih in zato delujejo čudežne moči v njem.',
        15: 'Drugi pa pravijo: Elija je; a drugi: prorok je, kakor eden izmed starih prorokov.',
        16: 'Ko pa sliši to Herod, reče: Janez, ki sem ga jaz dal obglaviti, je vstal.',
        17: 'Kajti ta Herod je bil poslal ujet Janeza ter ga vklenil v ječi zavoljo Herodiade, svojega brata Filipa žene; bil se je ž njo namreč oženil.',
        18: 'Janez pa je dejal Herodu: Ni ti dovoljeno, imeti svojega brata ženo.',
        19: 'Herodiada pa ga je zalezovala in hotela umoriti, pa ga ni mogla.',
        20: 'Zakaj Herod se je bal Janeza, vedoč, da je pravičen in svet mož, ter ga je varoval; in marsikaj je storil, kakor mu je on rekel, in rad ga je poslušal.',
        21: 'In je napočil prikladen dan: ko je Herod v spomin svojega rojstva napravil večerjo svojim velikašem in stotnikom in galilejskim prvakom,',
        22: 'je prišla noter njena, Herodiadina, hči in je plesala, ter se je prikupila Herodu in gostom. Kralj pa reče dekletu: Prosi me, karkoli hočeš, in dam ti.',
        23: 'In ji priseže: Karkoli me poprosiš, ti dam, do polovice kraljestva svojega.',
        24: 'Ona pa gre ven in reče materi svoji: Kaj naj si izprosim? Ta pa reče: Glavo Janeza Krstnika.',
        25: 'In gre precej jadrno h kralju in ga zaprosi, rekoč: Hočem, da mi daš pri tej priči v skledi glavo Janeza Krstnika.',
        26: 'In kralj postane silno žalosten, toda zavoljo prisege in gostov ji ni hotel odreči.',
        27: 'In precej pošlje kralj vojaka iz straže svoje in ukaže prinesti glavo njegovo. Ta pa odide in mu odseka v ječi glavo,',
        28: 'in prinese glavo njegovo v skledi in jo da dekletu, a dekle jo da materi svoji.',
        29: 'In ko so to slišali učenci njegovi, pridejo in vzemo truplo njegovo ter ga polože v grob.',
        30: 'In snidejo se apostoli pri Jezusu in mu sporočé vse, kar so storili in kar so ljudi naučili.',
        31: 'In jim reče: Pojdite sami na samoten kraj in malo počijte. Kajti bilo jih je veliko, ki so prihajali in odhajali, da še jesti niso utegnili.',
        32: 'Ter odidejo na ladji v samoten kraj sami.',
        33: 'In mnogi jih vidijo odhajati, in ko spoznajo, kam so namenjeni, hitro odrinejo tja peš iz vseh mest in jih še prehité.',
        34: 'In ko stopi Jezus z ladje, zagleda veliko množico, in se mu zasmilijo, zakaj bili so kakor ovce, ki nimajo pastirja. In začne jih učiti mnogo reči.',
        35: 'In ko je bila ura že pozna, pristopijo k njemu učenci njegovi in reko: Kraj je samoten in ura že pozna;',
        36: 'razpusti jih, da odidejo v dvore in vasi, ki so naokoli, ter si kupijo kaj za jed.',
        37: 'On pa odgovori in jim reče: Dajte jim vi jesti. Pa mu reko: Ali naj gremo in kupimo za dvesto denarjev kruha ter jim damo jesti?',
        38: 'On jim pa reče: Koliko hlebov imate? Pojdite in poglejte! In ko so izvedeli, reko: Pet in dve ribi.',
        39: 'In jim ukaže, naj jih posadé vse zaporedoma, omizje za omizjem, po zeleni travi.',
        40: 'In posedejo v skupinah po sto in po petdeset.',
        41: 'In vzame petere hlebe in tisti dve ribi in se ozre v nebo in jih blagoslovi, ter razlomi hlebe in podaje učencem svojim, naj polože prednje; tudi dve ribi razdeli vsem.',
        42: 'In vsi so jedli in se nasitili.',
        43: 'In pobrali so koscev dvanajst polnih košev in ostankov od rib.',
        44: 'In bilo jih je, ki so jedli hlebe, kakih pet tisoč mož.',
        45: 'In precej prisili učence svoje, naj stopijo v ladjo in se naprej prepeljejo proti Betsaidi, dokler on razpusti množico.',
        46: 'In poslovivši se od njih, odide na goro molit.',
        47: 'In ko se zvečeri, je ladja sredi morja in on sam na kopnem.',
        48: 'In zagleda jih, da se mučijo z veslanjem; pihal jim je namreč veter nasproti. In okoli četrte straže po noči pride k njim, hodeč po morju; in hotel je iti mimo njih.',
        49: 'Oni pa, videč ga, da hodi po morju, menijo, da je prikazen, in zakričé;',
        50: 'vsi so ga namreč zagledali in se prestrašili. In precej jih ogovori in jim reče: Srčni bodite, jaz sem, ne bojte se!',
        51: 'In stopi k njim v ladjo, in veter utihne. In presilno so se sami v sebi zavzemali;',
        52: 'kajti po tem, kar se je zgodilo pri hlebih, še niso prišli k spoznanju, temuč njih srce je odrevenelo.',
        53: 'In ko se prepeljejo, pridejo na kopno v Genezaret in potisnejo ladjo h kraju.',
        54: 'In ko stopijo z ladje, ga ljudje precej spoznajo,',
        55: 'ter obletajo vso tisto okolico in začno na posteljah prinašati bolnike tja, kjer so slišali, da biva.',
        56: 'In kamorkoli je prišel, v vasi ali v mesta ali v sela, so po ulicah pokladali bolnike in ga prosili, da bi se smeli dotekniti le roba njegove obleke; in katerikoli so se ga doteknili, so ozdraveli.',
    },
    7: {
        1: 'In snidejo se pri njem farizeji in nekateri pismarji, ki so prišli iz Jeruzalema.',
        2: 'Ti so videli nekatere učencev njegovih, da jedo kruh z nečistimi, to je z neumitimi rokami.',
        3: 'Farizeji in vsi Judje namreč ne jedo, dokler si skrbno ne umijejo rok, izpolnjujoč izročilo starih;',
        4: 'in kadar pridejo s trga, ne jedo, dokler se ne umijejo; in mnogo drugih reči je, ki so jih sprejeli in jih izpolnjujejo: umivanje kupic in vrčev in kotlov in stolov.',
        5: 'In vprašajo ga farizeji in pismarji: Zakaj se učenci tvoji ne ravnajo po izročilu starih, ampak jedo kruh z nečistimi rokami?',
        6: 'On pa jim reče: Dobro je prorokoval Izaija o vas hinavcih, kakor je pisano: „To ljudstvo me z ustnicami spoštuje, njih srce pa je daleč od mene;',
        7: 'ali zastonj me časté, učeč nauke, zapovedi človeške“.',
        8: 'Opustivši zapoved Božjo, izpolnjujete postave človeške.',
        9: 'In jim reče: Lepo zametujete zapoved Božjo, da ohranite izročilo svoje.',
        10: 'Mojzes namreč je rekel: „Spoštuj očeta svojega in mater svojo“in: „Kdor preklinja očeta ali mater, naj umre“.',
        11: 'Vi pa pravite: Če reče kdo očetu ali materi: S čimer bi ti jaz pomagal, bodi korban (to je: daritev) –',
        12: 'njemu ne pustite ničesar več storiti očetu svojemu ali materi svoji.',
        13: 'Tako podirate veljavo besede Božje z izročilom svojim, ki ste ga izročili; in mnogo temu podobnih reči počenjate.',
        14: 'In pokliče k sebi zopet ljudstvo ter jim reče: Poslušajte me vsi ter umejte!',
        15: 'Nič ne more človeka oskruniti, kar od zunaj prihaja vanj, marveč to, kar izhaja iz njega, oskrunja človeka.',
        16: 'Če ima kdo ušesa, da sliši, naj sliši!',
        17: 'In ko odide od ljudstva v hišo, ga vprašajo učenci njegovi o tej priliki.',
        18: 'Pa jim reče: Ali ste tudi vi tako nerazumni? Ne umete li, da ga vse to, kar od zunaj prihaja v človeka, ne more oskruniti?',
        19: 'ker ne gre v srce njegovo, ampak v trebuh in izhaja ven. S tem je proglasil za čiste vse jedi.',
        20: 'Reče pa: Kar iz človeka izhaja, to ga skruni.',
        21: 'Kajti od znotraj, iz srca človeškega, izhajajo hudobne misli, nečistosti, tatvine, uboji,',
        22: 'prešeštva, lakomnost, hudobnost, zvijača, požrešnost, nevoščljivo oko, preklinjanje Boga, napuh, nespametnost.',
        23: 'Vse te hudobne reči izhajajo od znotraj in skrunijo človeka.',
        24: 'In vstane in odide odtod, v kraje tirske in sidonske. In ko je stopil v hišo, ni hotel, da bi kdo zvedel o njem, ali ni se mogel prikriti.',
        25: 'Ampak precej, ko je slišala o njem, pride žena, katere hčerka je imela nečistega duha, in mu pade pred noge.',
        26: 'Bila pa je žena Grkinja, Sirofeničanka po rodu. In ga prosi, naj izžene zlega duha iz njene hčere.',
        27: 'Jezus pa ji reče: Pusti, da se poprej nasitijo otroci; kajti ni lepo, da se vzame kruh otrokom in se vrže psičkom.',
        28: 'Ona pa odgovori in mu reče: Da, Gospod, tudi psički pod mizo jedo od drobtinic otrok.',
        29: 'In ji reče: Zavoljo te besede pojdi; zli duh je odšel iz tvoje hčere.',
        30: 'In odide na svoj dom ter najde otroka ležečega na postelji, in zli duh je bil odšel.',
        31: 'In zopet odide iz tirskih krajev in pride skozi Sidon h Galilejskemu morju sredi po pokrajini Deseteromestja.',
        32: 'In pripeljejo mu gluhega, ki je nerazločno govoril, ter ga prosijo, naj bi položil nanj roko.',
        33: 'In vzame ga na stran od množice, mu položi prste svoje v ušesa in pljune in se dotakne jezika njegovega,',
        34: 'in pogledavši na nebo, vzdihne in mu veli: Efata, to je: Odpri se!',
        35: 'In odpro se ušesa njegova in razveže se vez jezika njegovega, in razločno je govoril.',
        36: 'In zapove jim, naj nikomur ne povedo; čim bolj jim je pa prepovedoval, tem bolj so razglaševali.',
        37: 'In presilno so se čudili, govoreč: Vse je prav storil; tudi gluhe napravlja, da slišijo, in neme, da govoré.',
    },
    8: {
        1: 'Tiste dni, ko je bilo zopet vse polno ljudstva pri njem in niso imeli kaj jesti, pokliče Jezus učence svoje in jim reče:',
        2: 'Ljudstvo se mi smili, ker že tri dni so pri meni in nimajo kaj jesti;',
        3: 'in če jih pustim lačne na njih dom, obnemorejo na poti; in nekateri od njih so prišli od daleč.',
        4: 'Pa mu odgovore učenci: Odkod bi jih mogel kdo tu v puščavi nasititi s kruhom?',
        5: 'In vpraša jih: Koliko imate hlebov? Oni pa reko: Sedem.',
        6: 'In zapove ljudstvu, naj posedejo po tleh. In vzame sedmere hlebe, zahvali, prelomi in podaje učencem svojim, naj polože prednje; in oni polagajo pred ljudstvo.',
        7: 'In imeli so nekaj ribic; in blagoslovi jih in reče, naj polože tudi te prednje.',
        8: 'In jedli so in se nasitili; in pobrali so ostanke koscev sedem košev.',
        9: 'Bilo jih je pa kake štiri tisoč. In jih razpusti.',
        10: 'In precej stopi v ladjo z učenci svojimi in pride v okraj Dalmanutski.',
        11: 'In farizeji izidejo in se začno ž njim prepirati, in so ga izkušali ter zahtevali od njega znamenje z neba.',
        12: 'In vzdihnivši v duhu svojem, reče: Kaj zahteva ta rod znamenja? Resnično vam pravim: Ne bo se dalo znamenje temu rodu.',
        13: 'In pusti jih ter stopi zopet v ladjo in odide na drugo stran.',
        14: 'In pozabili so vzeti kruha in niso imeli več nego en hleb s seboj v ladji.',
        15: 'Naroča jim pa, govoreč: Glejte, varujte se kvasu farizejskega in kvasu Herodovega.',
        16: 'In premišljajo sami pri sebi in govore: To pravi, ker kruha nimamo.',
        17: 'In ko Jezus to opazi, jim reče: Kaj premišljujete, da nimate kruha? ali še niste spoznali in še ne umejete? ali vam je še okamenelo srce?',
        18: 'Oči imate, in ne vidite? ušesa imate, in ne slišite? in ne pomnite li?',
        19: 'Ko sem pet hlebov razlomil med pet tisoč ljudi, koliko polnih košev ste nabrali drobtin? Reko mu: Dvanajst.',
        20: 'Ko sem jih pa sedem med štiri tisoč, koliko polnih pletenic ste nabrali drobtin? In reko mu: Sedem.',
        21: 'In jim reče: Ali še ne umejete?',
        22: 'In pridejo v Betsaido. In pripeljejo mu slepca in ga prosijo, naj se ga dotakne.',
        23: 'In prime slepca za roko in ga pelje ven iz vasi ter pljune v oči njegove, in položivši roke nanj, ga vpraša, če kaj vidi?',
        24: 'In izpregleda ter reče: Vidim ljudi, kajti kakor drevesa jih vidim, da okoli hodijo.',
        25: 'Potem mu zopet položi roke na oči, in on vidi razločno, in je ozdravel in videl bistro vse.',
        26: 'In ga odpravi na dom njegov, rekoč: Nikar ne hodi v vas!',
        27: 'In odide Jezus in učenci njegovi v vasi Cesareje Filipove, in po poti vpraša učence svoje, rekoč jim: Kdo pravijo ljudje, da sem jaz?',
        28: 'Oni mu pa povedo, rekoč: Janez Krstnik, in drugi: Elija, drugi pa: eden od prorokov.',
        29: 'In jih vpraša: Kdo pa pravite vi, da sem jaz? Peter odgovori in mu reče: Ti si Kristus.',
        30: 'In zapreti jim, naj nikomur ne pripovedujejo o njem.',
        31: 'In začne jih učiti, da mora Sin človekov mnogo pretrpeti in biti zavržen od starejšin in višjih duhovnikov in pismarjev in umorjen biti in v treh dneh od smrti vstati.',
        32: 'In to besedo je govoril prostosrčno. In Peter ga potegne na stran in ga začne odvračati.',
        33: 'On pa se obrne in pogleda učence svoje in zapreti Petru in reče: Poberi se od mene, satan! ker ne misliš, kar je Božjega, ampak kar je človeškega.',
        34: 'In pokliče ljudstvo z učenci svojimi ter jim reče: Kdor hoče za menoj iti, naj zataji samega sebe in vzame križ svoj nase in gre za menoj.',
        35: 'Kajti kdorkoli hoče življenje svoje ohraniti, ga izgubi, kdor pa izgubi življenje svoje zaradi mene in evangelija, ta ga ohrani.',
        36: 'Kaj namreč pomaga človeku, če ves svet pridobi, duši svoji pa škoduje?',
        37: 'Kajti kaj more dati človek v zameno za dušo svojo?',
        38: 'Zakaj kdor se sramuje mene in besed mojih v tem prešeštnem in grešnem rodu, sramoval se bo tudi Sin človekov njega, kadar pride v slavi Očeta svojega s svetimi angeli.',
    },
    9: {
        1: 'In jim reče: Resnično vam pravim, da so nekateri med tukaj stoječimi, ki ne bodo okusili smrti, dokler ne vidijo kraljestva Božjega, da je prišlo z močjo.',
        2: 'In čez šest dni vzame Jezus Petra in Jakoba in Janeza in jih odpelje na visoko goro same posebe; in izpremeni se pred njimi.',
        3: 'In oblačila njegova postanejo bleščeča in zelo bela kakor sneg, kakor jih noben belilec na zemlji ne more ubeliti.',
        4: 'In prikaže se jim Elija z Mojzesom, in pogovarjata se z Jezusom.',
        5: 'In Peter izpregovori in reče Jezusu: Rabi, dobro nam je tu biti; pa naredimo tri šatore, tebi enega in Mojzesu enega in Eliju enega.',
        6: 'Ni namreč vedel, kaj bi odgovoril, kajti bili so zelo uplašeni.',
        7: 'In nastane oblak in jih obsenči, in glas pride iz oblaka: Ta je Sin moj ljubljeni; njega poslušajte.',
        8: 'In nagloma se ozro in nikogar več ne vidijo razen Jezusa samega s seboj.',
        9: 'Ko so pa stopali z gore, jim zapove, naj nikomur ne pripovedujejo, kar so videli, dokler Sin človekov ne vstane iz mrtvih.',
        10: 'In to besedo so ohranili, in vpraševali so med seboj, kaj bi to bilo: vstati iz mrtvih?',
        11: 'In vprašajo ga, rekoč: Saj pravijo pismarji, da mora Elija poprej priti?',
        12: 'On pa jim reče: Elija res pride poprej in uravna vse vnovič. A kako je pisano o Sinu človekovem, da mora mnogo pretrpeti in ga bodo za nič šteli?',
        13: 'Ali pravim vam, da je Elija že prišel, in so mu storili, karkoli so hoteli, kakor je pisano o njem.',
        14: 'In ko pridejo k učencem, ugledajo veliko množico okoli njih in pismarje, da se ž njimi prepirajo.',
        15: 'In vsa množica se precej, ko ga ugleda, začudi, in hité k njemu in ga pozdravljajo.',
        16: 'In jih vpraša: Kaj se prepirate ž njimi?',
        17: 'In eden iz množice odgovori: Učenik, pripeljal sem k tebi sina svojega, ki ima nemega duha.',
        18: 'In kjerkoli ga zgrabi, ga meče, in on se peni in škriplje z zobmi, in se suši. Pa sem dejal učencem tvojim, naj ga izženo, a niso mogli.',
        19: 'On pa jim odgovori in reče: O neverni rod, doklej bom z vami? doklej vas bom trpel? Pripeljite ga k meni!',
        20: 'In pripeljejo ga k njemu. Komaj ga pa duh ugleda, ga precej strese, da se zgrudi na tla ter se valja in peni.',
        21: 'In vpraša očeta njegovega: Koliko časa je, odkar se mu je to zgodilo? Ta pa reče: Od malih nog.',
        22: 'In mnogokrat ga vrže tudi v ogenj ali v vodo, da ga pogubi. Ali, če moreš kaj, usmili se nas in pomagaj nam.',
        23: 'Jezus pa mu reče: Če moreš kaj! Vse je mogoče tistemu, ki veruje.',
        24: 'Precej zavpije dečkov oče in s solzami reče: Verujem, Gospod, pomagaj neveri moji!',
        25: 'Videč pa Jezus, da se steka ljudstvo, zapreti nečistemu duhu, rekoč mu: Duh nemi in gluhi, jaz ti ukazujem, zapusti ga in ne pridi več vanj!',
        26: 'In zakriči in ga močno strese in izide iz njega. In deček postane kakor mrtev, tako da mnogi pravijo, da je umrl.',
        27: 'Jezus pa ga prime za roko in ga vzdigne; in vstal je.',
        28: 'In ko pride v hišo, ga vprašajo učenci njegovi na samem: Kako, da ga mi nismo mogli izgnati?',
        29: 'In reče jim: Ta rod ne more iziti z ničimer razen z molitvijo in postom.',
        30: 'In ko so se odpravili odtod, so šli skozi Galilejo, in ni hotel, da bi kdo zvedel.',
        31: 'Kajti učil je učence svoje in jim pravil: Sin človekov bo izdan v človeške roke, in umorili ga bodo; in ko bo umorjen, vstane tretji dan od smrti.',
        32: 'Oni pa niso umeli tega govora, a bali so se ga vprašati.',
        33: 'In pridejo v Kafarnavm. In ko so bili v hiši, jih vpraša: Kaj ste se po poti med seboj menili?',
        34: 'Oni pa molče; spotoma so se bili namreč med seboj prepirali, kdo da je največji.',
        35: 'In ko sede, pokliče dvanajstere in jim reče: Če kdo hoče biti prvi, bodi najzadnji od vseh in vsem služabnik.',
        36: 'In vzame otročiča ter ga postavi v sredo mednje, in ga vzame v naročje in jim reče:',
        37: 'Kdor sprejme enega takih otročičev v mojem imenu, mene sprejme, in kdor mene sprejme, ne sprejme mene, marveč njega, ki me je poslal.',
        38: 'Reče mu Janez: Učenik, videli smo nekoga, ki ne hodi za nami, da je z imenom tvojim izganjal hudiče, in smo mu zabranili, ker ne hodi za nami.',
        39: 'Jezus mu pa reče: Ne branite mu, zakaj nikogar ni, ki bi storil čudež z imenom mojim in bi mogel brž slabo govoriti o meni.',
        40: 'Kdor namreč ni zoper nas, je z nami.',
        41: 'Kajti kdorkoli vas napoji s kupico vode v imenu mojem, ker ste Kristusovi, resnično vam pravim, ne izgubi plačila svojega.',
        42: 'In kdor pohujša enega teh malih, ki verujejo v me, bi mu bilo bolje, da mu obesijo mlinski kamen na vrat in da ga vržejo v morje.',
        43: 'In če te pohujšuje roka tvoja, odsekaj jo; bolje ti je brez roke priti v življenje nego imeti obe roki in oditi v pekel, v ogenj neugasljivi',
        44: '§ kjer njih črv ne umira in ogenj ne ugasne.',
        45: 'In če te noga tvoja pohujšuje, odsekaj jo; bolje ti je hromemu priti v življenje nego imeti obe nogi in vrženemu biti v pekel ognjeni',
        46: '§ kjer njih črv ne umira in ogenj ne gasne.',
        47: 'In če te oko tvoje pohujšuje, izderi ga; bolje ti je z enim očesom priti v kraljestvo Božje nego imeti dve očesi in vrženemu biti v pekel ognjeni,',
        48: 'kjer njih črv ne umira in ogenj ne gasne.',
        49: 'Kajti vsak bo z ognjem osoljen, in vsaka žrtev bo s soljo osoljena.',
        50: 'Dobra je sol, če pa sol postane neslana, s čim jo boste osolili? Imejte v sebi sol, in mir imejte med seboj.',
    },
    10: {
        1: 'In se odpravi odtod in pride v Judejsko pokrajino in za Jordan. In snidejo se zopet množice k njemu, in kakor je imel navado, jih je zopet učil.',
        2: 'In pristopijo k njemu farizeji in ga vprašajo, izkušajoč ga: Ali je dovoljeno možu, ločiti se od žene?',
        3: 'On pa odgovori in jim reče: Kaj vam je zapovedal Mojzes?',
        4: 'Oni pa reko: Mojzes je dopustil ločitni list napisati in jo pustiti.',
        5: 'Jezus pa jim reče: Zavoljo trdosrčnosti vaše vam je napisal to zapoved.',
        6: 'Od začetka stvarjenja pa ju je kot moža in ženo ustvaril Bog.',
        7: '„Zato zapusti človek očeta svojega in mater svojo in se pridruži ženi svoji,',
        8: 'in ta dva bodeta eno meso.“Tako nista več dva, temuč eno meso.',
        9: 'Kar je torej Bog združil, naj človek ne razdružuje.',
        10: 'In v hiši ga zopet učenci vprašajo o tej reči.',
        11: 'Pa jim reče: Kdor se loči od žene svoje in se oženi z drugo, prešeštvuje zoper njo;',
        12: 'in ako se žena loči od moža svojega in se omoži z drugim, prešeštvuje.',
        13: 'In prinašali so k njemu otročiče, da bi se jih dotaknil; učenci pa jih okarajo.',
        14: 'Videč pa to Jezus, se razhudi in jim reče: Pustite otročiče, naj pridejo k meni, ne branite jim; zakaj takih je kraljestvo Božje.',
        15: 'Resnično vam pravim: Kdor ne sprejme kraljestva Božjega kakor otrok, nikakor ne pride vanj.',
        16: 'In jemlje jih v naročje ter polagajoč nanje roke, jih blagoslavlja.',
        17: 'In ko gre ven na cesto, pribeži eden k njemu, poklekne pred njim in ga vpraša: Dobri učenik, kaj naj storim, da podedujem večno življenje?',
        18: 'Jezus pa mu reče: Kaj me imenuješ dobrega? Nihče ni dober razen eden, Bog.',
        19: 'Zapovedi znaš: „Ne ubijaj, ne prešeštvuj, ne kradi, ne pričaj po krivem, ne goljufaj, spoštuj očeta svojega in mater“.',
        20: 'On pa odgovori in mu reče: Učenik, vse to sem izpolnjeval od mladosti svoje.',
        21: 'Jezus pa pogleda nanj, in ker ga je ljubil, mu reče: Enega ti je še treba. Pojdi, prodaj, karkoli imaš, in daj ubogim, in imel boš zaklad v nebesih; ter pridi in hodi za menoj.',
        22: 'Njemu pa zagreni ta beseda in odide žalosten, zakaj imel je mnogo premoženja.',
        23: 'In Jezus pogleda okoli in reče učencem svojim: Kako težko pridejo tisti, ki imajo bogastvo, v kraljestvo Božje!',
        24: 'Učenci pa so se zavzeli ob besedah njegovih. Jezus pa zopet odgovori in jim reče: Otroci, kako težko je tistim, ki stavijo svoje upanje v bogastvo, priti v kraljestvo Božje!',
        25: 'Laže je velblodu iti igli skozi ušesce nego bogatemu priti v kraljestvo Božje!',
        26: 'Oni pa se zelo zgroze in govore med seboj: Kdo se potem more zveličati?',
        27: 'Jezus pa pogleda nanje in reče: Pri ljudeh je nemogoče, ali ne pri Bogu; kajti vse je mogoče pri Bogu.',
        28: 'Peter mu začne praviti: Glej, mi smo zapustili vse in smo šli za teboj.',
        29: 'Jezus reče: Resnično vam pravim, nikogar ni, ki je zapustil hišo, ali brate, ali sestre, ali očeta, ali mater, ali ženo, ali otroke, ali njive zavoljo mene in evangelija,',
        30: 'da ne bi prejel sedaj v tem času stokrat toliko: hiš in bratov in sester in mater in otrok in njiv s preganjanjem, in v prihodnjem svetu večnega življenja.',
        31: 'Mnogi pa, ki so prvi, bodo zadnji, in ki so zadnji, prvi.',
        32: 'Bili pa so na poti, grede v Jeruzalem; in Jezus je šel pred učenci, in oni so se čudili. Tisti pa, ki so šli za njim, so se bali. In vzame zopet dvanajstere k sebi in jim začne praviti, kaj se mu ima zgoditi:',
        33: 'Glejte, gori v Jeruzalem gremo, in Sin človekov bo izdan višjim duhovnikom in pismarjem, in obsodijo ga na smrt in izroče poganom,',
        34: 'in zasramovali ga bodo in pljuvali nanj in ga bičali in umorili; a tretji dan vstane od smrti.',
        35: 'In pristopita k njemu Jakob in Janez, sina Zebedejeva, ter mu rečeta: Učenik, hočeva, da nama storiš, kar bova prosila.',
        36: 'On pa ju vpraša: Kaj hočeta, da naj vama storim?',
        37: 'Ona pa mu rečeta: Daj nama, da bova sedela eden tebi na desnici in eden na levici v slavi tvoji.',
        38: 'Jezus pa jima reče: Ne vesta, kaj prosita. Moreta li piti kelih, ki ga pijem jaz, in se krstiti s krstom, ki se jaz krstim ž njim?',
        39: 'Ona pa rečeta: Moreva. A Jezus jima veli: Kelih, ki ga jaz pijem, bosta pila, in s krstom, ki se jaz krstim ž njim, se bosta krstila.',
        40: 'Da bi pa sedela meni na desnici in na levici, ne morem dati jaz, a dá se to tistim, katerim je pripravljeno.',
        41: 'In ko slišijo to deseteri, se začno jeziti nad Jakobom in Janezom.',
        42: 'Jezus jih pa pokliče in jim reče: Veste, da tisti, ki veljajo za vladarje narodov, nad njimi gospodujejo, in njih velikaši jih siloma vladajo.',
        43: 'Ni pa tako med vami: ampak kdorkoli hoče postati velik med vami, naj vam bode služabnik,',
        44: 'in kdorkoli hoče med vami biti prvi, bodi vsem hlapec.',
        45: 'Kajti tudi Sin človekov ni prišel, da njemu služijo, ampak da služi in dá življenje svoje v odkupnino za mnoge.',
        46: 'In pridejo v Jeriho. In ko so šli iz Jeriha, on in učenci njegovi in obilna množica, je sedel kraj poti slep berač, Bartimej, sin Timejev.',
        47: 'In ko sliši, da je Jezus Nazarečan, začne vpiti in govoriti: Sin Davidov, Jezus, usmili se me!',
        48: 'In mnogi mu prete, naj umolkne; a on le še bolj kriči: Sin Davidov, usmili se me!',
        49: 'In Jezus se ustavi in veli: Pokličite ga! In pokličejo slepca in mu reko: Srčen bodi, vstani, kliče te.',
        50: 'On pa vrže s sebe plašč svoj, poskoči in pride k Jezusu.',
        51: 'In Jezus mu odgovori in reče: Kaj hočeš, da naj ti storim? Slepec pa mu reče: Rabuni, da izpregledam!',
        52: 'In Jezus mu veli: Pojdi, vera tvoja te je rešila. In precej je izpregledal, in za Jezusom je šel po poti.',
    },
    11: {
        1: 'In ko so se približevali Jeruzalemu, Betfagi in Betaniji pri Oljski gori, pošlje dva izmed učencev svojih',
        2: 'in jima reče: Pojdita v vas, ki vama je nasproti, in precej, ko prideta vanjo, najdeta žrebe privezano, ki na njem še noben človek ni sedel: odvežita ga in pripeljita.',
        3: 'In če vama kdo reče: Kaj delata to? recita: Gospod ga potrebuje in precej ga zopet pošlje sem.',
        4: 'In odideta ter najdeta žrebe privezano pri vratih zunaj na ulici in ga odvežeta.',
        5: 'In nekateri tistih, ki so ondi stali, jima reko: Kaj delata, da odvezujeta žrebe?',
        6: 'Ona pa jim rečeta, kakor je bil Jezus naročil; in ju puste.',
        7: 'In pripeljeta žrebe k Jezusu in denejo nanje oblačila svoja, in on sede nanje.',
        8: 'Mnogi pa pogrnejo oblačila svoja po cesti; a drugi steljejo mladičje, ki so ga nasekali po polju.',
        9: 'In tisti, ki ga spremljajo spredaj in zadaj, kličejo: Hosana! Blagoslovljen, ki prihaja v imenu Gospodovem!',
        10: 'Blagoslovljeno kraljestvo, ki prihaja, kraljestvo očeta našega Davida! Hosana na višavah!',
        11: 'In Jezus pride v Jeruzalem in v tempelj; in ko si je vse ogledal, odide, ker je bil že večer, z dvanajsterimi v Betanijo.',
        12: 'In ko so drugi dan šli iz Betanije, postane lačen.',
        13: 'In ugleda od daleč smokvo, ki je imela listje, pa pride, če morda kaj najde na njej; toda ko pristopi k njej, ne najde ničesar razen listja, kajti še ni bil čas za smokve.',
        14: 'In Jezus izpregovori in ji reče: Na vekomaj nikoli nihče s tebe sadu ne jej! In slišali so to učenci njegovi.',
        15: 'In pridejo v Jeruzalem. In ko stopi Jezus v tempelj, začne izganjati tiste, ki so v templju prodajali in kupovali, in prevrne mize menjalcem in stole prodajalcem golobov',
        16: 'in ne pusti, da bi kdo nesel posodo skozi tempelj.',
        17: 'In uči jih in jim reče: Mar ni pisano: „Dom moj naj se imenuje dom molitve vsem narodom“? A vi ste naredili iz njega razbojniško jamo.',
        18: 'In slišali so to višji duhovniki in pismarji in so iskali, kako bi ga pogubili; zakaj bali so se ga, ker se je vse ljudstvo čudilo nauku njegovemu.',
        19: 'In vsak večer je šel ven iz mesta.',
        20: 'In ko gredo zjutraj mimo, ugledajo smokvo, da je suha do korenine.',
        21: 'In Peter se spomni in mu reče: Rabi, glej, smokva, ki si jo preklel, se je posušila.',
        22: 'Jezus pa odgovori in jim veli: Imejte vero v Boga!',
        23: 'Resnično vam pravim: Če kdo reče tej gori: Vzdigni se in vrzi se v morje, in ne dvomi v srcu svojem, temuč veruje, da se zgodi, kar pravi, zgodilo se mu bode.',
        24: 'Zato vam pravim: Vse, karkoli v molitvi svoji prosite, verujte, da ste prejeli, in zgodi se vam.',
        25: 'In kadar stopite k molitvi, odpustite, če imate zoper koga kaj, da tudi Oče vaš, ki je v nebesih, vam odpusti vaše pregrehe.',
        26: '§ Če pa vi ne odpustite, tudi vam ne odpusti Oče vaš, ki je v nebesih, vaših pregreškov.',
        27: 'In pridejo zopet v Jeruzalem. In ko se je v templju izprehajal, pridejo k njemu višji duhovniki in pismarji in starejšine',
        28: 'in mu reko: S kakšno oblastjo delaš to? ali kdo ti je dal to oblast, da to delaš?',
        29: 'Jezus pa jim reče: Vprašal vas bom eno besedo, in odgovorite mi, pa vam povem, s kakšno oblastjo to delam.',
        30: 'Krst Janezov, je li bil iz nebes ali od ljudi? Odgovorite mi!',
        31: 'In premišljevali so sami pri sebi, govoreč: Če rečemo: Iz nebes, poreče: Zakaj mu torej niste verovali?',
        32: 'Če pa rečemo: Od ljudi – bali so se ljudstva; kajti vsi so mislili o Janezu, da je bil res prorok.',
        33: 'Pa odgovore Jezusu in reko: Ne vemo. In Jezus jim reče: Tudi jaz vam ne povem, s kakšno oblastjo to delam.',
    },
    12: {
        1: 'In začne jim govoriti v prilikah: Zasadil je človek vinograd in ga ogradil s plotom, in je izkopal klet in je sezidal stolp, in ga je izročil vinogradnikom, ter je odpotoval.',
        2: 'In ko je bilo čas, pošlje k vinogradnikom hlapca, da bi od vinogradnikov prejel pridelkov iz vinograda.',
        3: 'Oni pa ga zgrabijo in pretepo in pošljejo praznega.',
        4: 'In zopet pošlje k njim drugega hlapca; in temu razbijejo glavo in ga osramoté.',
        5: 'In pošlje drugega, in tega ubijejo, in mnogo drugih, ki jih nekatere pretepo in nekatere ubijejo.',
        6: 'Še enega je imel, sina ljubljenega: tega pošlje naposled k njim, rekoč: Sina mojega se bodo bali.',
        7: 'Oni pa, vinogradniki, reko med seboj: Ta je dedič. Pridite, ubijmo ga, in naša bo dediščina.',
        8: 'Ter ga zgrabijo in ubijejo, in ga vržejo ven iz vinograda.',
        9: 'Kaj bo torej storil gospodar vinograda? Pride in vinogradnike pogubi, in vinograd dá drugim.',
        10: 'Niste li brali tudi tega pisma: „Kamen, ki so ga zidarji zavrgli, ta je postal glava voglu;',
        11: 'od Gospoda se je zgodilo to, in čudno je v očeh naših“.',
        12: 'In gledali so, da bi ga ujeli, ali zbojé se ljudstva. Spoznali so namreč, da je zoper nje povedal to priliko. In pustili so ga ter odšli.',
        13: 'In pošljejo k njemu nekatere farizejev in Herodovcev, da bi ga ujeli v besedi.',
        14: 'In ko pridejo, mu reko: Učenik, vemo, da si resničen, in ti ni nikogar mar, kajti ne gledaš ljudem na lice, temuč v resnici učiš pot Božjo. Ali je prav dati cesarju davek ali ne? Naj ga damo ali ne damo?',
        15: 'On pa, ker je spoznal njih hinavstvo, jim reče: Kaj me izkušate? Prinesite mi denar, da pogledam.',
        16: 'Oni pa prineso. In jim reče: Čigava je ta podoba in napis? Oni mu pa reko: Cesarjeva.',
        17: 'Jezus pa jim veli: Dajte cesarju, kar je cesarjevega, in Bogu, kar je Božjega. In silno se mu začudijo.',
        18: 'In pridejo k njemu saduceji, ki pravijo, da ni vstajenja, in ga vprašajo, govoreč:',
        19: 'Učenik! Mojzes nam je napisal: Če komu brat umre in zapusti ženo, otrok pa ne zapusti, naj vzame njegov brat ženo njegovo in zbudi seme bratu svojemu.',
        20: 'Bilo je sedem bratov; in prvi vzame ženo in umre, in ne zapusti zaroda.',
        21: 'In vzame jo drugi in umre, ne zapustivši zaroda. Tudi tretji tako.',
        22: 'In vseh sedem ne zapusti zaroda. Naposled za vsemi umre tudi žena.',
        23: 'Ob vstajenju torej, ko vstanejo, čigava izmed njih bo žena? Kajti sedmeri so jo imeli za ženo.',
        24: 'Jezus jim reče: Se li ne motite zato, ker ne poznate pisem, ne moči Božje?',
        25: 'Kadar namreč iz mrtvih vstanejo, se ne ženijo in ne možé, ampak so kakor angeli v nebesih.',
        26: 'Za mrtve pa, da vstajajo, niste li brali v Mojzesovi knjigi, pri grmu, kako mu je Bog govoril, rekoč: „Jaz sem Bog Abrahamov in Bog Izakov in Bog Jakobov“?',
        27: 'On ni Bog mrtvih, ampak živih. Zelo se motite.',
        28: 'In pristopi eden pismarjev, ki je slišal, kako so se prepirali, in ker je videl, da jim je dobro odgovoril, ga vpraša: Katera je prva zapoved od vseh?',
        29: 'Jezus odgovori: Prva je: „Sliši, Izrael! Gospod, naš Bog, je edini Gospod.',
        30: 'In ljubi Gospoda, Boga svojega, iz vsega srca svojega in iz vse duše svoje in iz vse pameti svoje in iz vse moči svoje.“',
        31: 'Druga je ta: „Ljubi bližnjega svojega kakor samega sebe“. Večje od teh ni druge zapovedi.',
        32: 'In reče mu pismar: Dobro, učenik; po resnici si povedal, da je Bog eden, in da ni drugega razen njega;',
        33: 'in ljubiti ga iz vsega srca in iz vse pameti in iz vse moči, in bližnjega ljubiti kakor samega sebe: to je več od vseh žgalnih žrtev in daritev.',
        34: 'In Jezus, videč, da je pametno odgovoril, mu reče: Nisi daleč od kraljestva Božjega. In nihče si ga ni upal več vprašati.',
        35: 'In Jezus odgovori in reče, učeč v templju: Kako pravijo pismarji, da je Kristus sin Davidov?',
        36: 'Sam David je dejal v svetem Duhu: „Rekel je Gospod Gospodu mojemu: Sedi na desnico mojo, dokler ne položim sovražnikov tvojih nogam tvojim za podnožje“.',
        37: 'Sam David ga imenuje Gospoda; odkod pa je on sin njegov? In preprosto ljudstvo ga je rado poslušalo.',
        38: 'In govoril jim je v nauku svojem: Varujte se pismarjev, ki radi hodijo v dolgih suknjah in ljubijo pozdrave po ulicah',
        39: 'in prve stole po shodnicah in prva mesta pri gostijah;',
        40: 'ki požirajo vdovam hiše in na videz opravljajo dolge molitve. Ti bodo prejeli ostrejšo sodbo.',
        41: 'In sede Jezus temepljskemu zakladu nasproti in gleda, kako meče ljudstvo denar v zakladnico; in veliko bogatih je metalo mnogo.',
        42: 'In pride vdova uboga in vrže dva denarca, kar je en vinar.',
        43: 'In pokliče učence svoje in jim reče: Resnično vam pravim, da je ta vdova uboga vrgla več nego vsi, ki mečejo v zakladnico:',
        44: 'kajti vsi so vrgli od obilnosti svoje, ta pa je od uboštva svojega vrgla vse, kar je imela, ves živež svoj.',
    },
    13: {
        1: 'In ko je šel iz templja, mu reče eden učencev njegovih: Učenik, glej, kakšno kamenje in kakšne stavbe!',
        2: 'In Jezus mu reče: Vidiš te velike stavbe? Ne ostane tu kamen na kamenu, ki bi se ne podrl.',
        3: 'In ko je sedel na Oljski gori templju nasproti, ga vprašajo posebe Peter in Jakob in Janez in Andrej:',
        4: 'Povej nam, kdaj bode to? in kaj bode znamenje, ko se ima vse to dopolniti?',
        5: 'Jezus jim pa začne praviti: Varujte se, da vas kdo ne zapelje!',
        6: 'Kajti veliko jih pride z imenom mojim, govoreč: Jaz sem Kristus, in mnogo jih bodo zapeljali.',
        7: 'Kadar pa zaslišite boje in glasove o bojih, ne ustrašite se; zakaj to mora biti, ali to še ni konec.',
        8: 'Kajti vstane narod zoper narod in kraljestvo zoper kraljestvo; potresi bodo po krajih, in bodo lakote. Začetek nadlogam je to.',
        9: 'Vi pa varujte sebe! Kajti izročali vas bodo sodiščem in v shodnicah vas bodo pretepali in pred vladarje in kralje vas postavljali zavoljo mene, njim za pričevanje.',
        10: 'In med vsemi narodi se mora poprej oznaniti evangelij.',
        11: 'Kadar vas pa popeljejo, da vas izroče, ne skrbite naprej, kaj bi govorili, temuč kar vam bo dano tisto uro, to govorite; ker niste vi, ki govorite, ampak sveti Duh.',
        12: 'Izdajal pa bo brat brata na smrt in oče sina, in otroci bodo vstali zoper roditelje in jih bodo morili.',
        13: 'In vsi vas bodo sovražili zaradi imena mojega. Kdor pa pretrpi do konca, ta bo zveličan.',
        14: 'A kadar ugledate gnusobo razdejanja, da stoji, kjer ne bi smela (kdor bere, naj razume!), tedaj naj tisti, ki so v Judeji, zbežé na gore;',
        15: 'a kdor je na strehi, ne stopaj doli in ne hodi noter, da bi kaj vzel iz hiše svoje;',
        16: 'in kdor je na polju, naj se ne vrača, da vzame plašč svoj.',
        17: 'Gorje pa nosečim in doječim v tistih dneh!',
        18: 'Molite pa, da ne bode po zimi.',
        19: 'Kajti tisti dnevi bodo stiska, kakršne ni bilo od začetka stvarjenja, katero je ustvaril Bog, do sedaj in je tudi ne bo.',
        20: 'In ko ne bi bil Gospod prikrajšal teh dni, ne bi se rešil noben človek; ali zavoljo izvoljencev, ki jih je izvolil, je prikrajšal te dni.',
        21: 'In če vam tedaj kdo reče: Glej, tu je Kristus, ali: Glej, ondi je, ne verjemite.',
        22: 'Kajti lažnivi kristusi in lažnivi proroki bodo vstali in delali znamenja in čudeže, da bi premotili, ko bi bilo mogoče, izvoljence.',
        23: 'A vi se varujte; glejte, povedal sem vam vse naprej.',
        24: 'Ali v tistih dneh, po tej stiski, otemni solnce in mesec ne bo dajal svetlobe svoje,',
        25: 'in zvezde bodo padale z neba, in sile, ki so na nebu, se bodo pregibale.',
        26: 'In tedaj ugledajo Sina človekovega, da prihaja na oblakih z veliko močjo in slavo.',
        27: 'In tedaj pošlje angele svoje in zbere izvoljence svoje od četverih vetrov, od konca zemlje do kraja neba.',
        28: 'Od smokve pa se učite prilike: Kadar se že njena veja omladi in požene listje, veste, da je blizu poletje.',
        29: 'Tako tudi vi: kadar ugledate, da se te reči gode, vedite, da je on blizu, pri vratih.',
        30: 'Resnično vam pravim, da ne preide ta rod, dokler se vse te reči ne zgode.',
        31: 'Nebo in zemlja preideta, a besede moje nikoli ne preidejo.',
        32: 'Za tisti dan in tisto uro pa nihče ne ve, tudi angeli v nebesih ne, tudi Sin ne, samo Oče.',
        33: 'Pazite, bedite in molite, kajti ne veste, kdaj je ta čas.',
        34: 'Kakor je človek, ki je odpotoval, zapustil dom svoj in dal hlapcem svojim oblast in vsakemu svoje delo, tudi vratarju zapovedal, da naj čuje –.',
        35: 'Čujte torej, kajti ne veste, kdaj pride gospodar hiše: ali zvečer, ali opolnoči, ali o petelinovem petju, ali zjutraj,',
        36: 'da vas, ko pride nagloma, ne najde spečih.',
        37: 'Kar pa vam pravim, pravim vsem: Čujte!',
    },
    14: {
        1: 'Bila je pa Velika noč in praznik presnih kruhov čez dva dni. In višji duhovniki in pismarji so gledali, kako bi ga z zvijačo ujeli in umorili.',
        2: 'Kajti govorili so: Ne na praznik, da se morda ljudstvo ne upre.',
        3: 'In ko je bil v Betaniji, v hiši Simona gobavca, in je sedel za mizo, pride žena, ki je imela alabastrovo posodo mazila iz čiste, dragocene narde; in razbije posodo in mu ga izlije na glavo.',
        4: 'Bili pa so tu nekateri, ki so se sami pri sebi hudovali: Čemu se je zgodila ta potrata mazila?',
        5: 'Kajti to mazilo bi se bilo lahko prodalo za več nego tristo denarjev in izkupilo dalo ubogim. In so godrnjali nad njo.',
        6: 'Jezus pa reče: Pustite jo! kaj jo nadlegujete? Dobro delo je storila na meni.',
        7: 'Kajti uboge imate vedno pri sebi, in kadar hočete, jim morete dobro storiti, mene pa nimate vselej.',
        8: 'Kar je mogla, je storila: vnaprej je pomazilila telo moje za pokop.',
        9: 'Resnično pa vam pravim: Kjerkoli po vsem svetu se bo oznanjal ta evangelij, povedalo se bo tudi to, kar je ona storila, njej v spomin.',
        10: 'In Juda Iškariot, eden od dvanajsterih, odide k višjim duhovnikom, da jim ga izda.',
        11: 'Oni pa se razvesele, ko to slišijo, in mu obljubijo dati denarja. In iskal je, kako bi ga o priliki izdal.',
        12: 'In prvi dan presnih kruhov, ko so klali velikonočno jagnje, mu reko učenci njegovi: Kam hočeš, da gremo in pripravimo, da boš jedel velikonočno jagnje?',
        13: 'In pošlje dva učencev svojih in jima reče: Pojdita v mesto, in srečal vaju bo človek, ki nese vrč vode. Pojdita za njim,',
        14: 'in kjer vnide, recita hišnemu gospodarju: Učenik pravi: Kje je obednica, kjer bom z učenci svojimi jedel velikonočno jagnje?',
        15: 'In on vama pokaže veliko izbo, pogrnjeno in pripravljeno; tam nam pripravita.',
        16: 'In učenca odideta in prideta v mesto in najdeta, kakor jima je rekel, ter pripravita jagnje.',
        17: 'In ko se zvečeri, pride z dvanajsterimi.',
        18: 'In ko so za mizo sedeli in jedli, reče Jezus: Resnično vam pravim, da me eden izmed vas, ki z menoj jé, izda.',
        19: 'Oni se pa začno žalostiti in mu praviti eden za drugim: Ali jaz?',
        20: 'On pa jim reče: Eden dvanajsterih, ki omaka z menoj v skledi.',
        21: 'Sin človekov sicer gre, kakor je pisano o njem; ali gorje tistemu človeku, ki Sina človekovega izdaja! Bolje bi bilo tistemu človeku, da ne bi bil rojen.',
        22: 'In ko so jedli, vzame Jezus kruh in blagoslovi in ga prelomi in jim da in reče: Vzemite! to je moje telo.',
        23: 'In vzame kelih, se zahvali in jim da; in vsi so pili iz njega.',
        24: 'In jim reče: To je moja kri nove zaveze, ki se preliva za mnoge.',
        25: 'Resnično vam pravim, da ne bom več pil od trtnega sadu do tistega dne, ko ga bom pil novega v kraljestvu Božjem.',
        26: 'In ko so odpeli zahvalnico, odidejo na Oljsko goro.',
        27: 'In jim reče Jezus: Vsi se boste pohujšali, kajti pisano je: „Pastirja udarim in ovce se razkrope“.',
        28: 'Ali po vstajenju svojem pojdem pred vami v Galilejo.',
        29: 'Peter pa mu reče: Če se tudi vsi pohujšajo, jaz vendar ne.',
        30: 'Pa mu reče Jezus: Resnično ti pravim, da me danes še, to noč, preden petelin dvakrat zapoje, zatajiš trikrat.',
        31: 'On pa govori tem bolj goreče: Ko bi moral s teboj umreti, te gotovo ne zatajim. Tako so pa tudi vsi govorili.',
        32: 'In pridejo v ograd, ki mu je ime Getsemane, ter veli učencem svojim: Sedite tu dotlej, da pomolim.',
        33: 'In vzame Petra in Jakoba in Janeza s seboj. In začne žalovati in trepetati v grozi.',
        34: 'In jim reče: Žalostna je duša moja do smrti; ostanite tu in čujte.',
        35: 'Ter odide malo dalje in pade na zemljo in moli, naj preide, če je mogoče, ta ura mimo njega,',
        36: 'in govori: Aba, Oče! vse je mogoče tebi, vzemi ta kelih od mene, toda ne, kar jaz hočem, ampak kar hočeš ti.',
        37: 'In pride in jih najde speče ter reče Petru: Simon, spiš? Ali nisi mogel ene ure prečuti?',
        38: 'Čujte in molite, da ne zajdete v izkušnjavo; duh je sicer voljan, ali meso je slabo.',
        39: 'In zopet odide in moli, govoreč iste besede.',
        40: 'In ko se vrne, jih najde zopet speče, bile so jim namreč oči preutrujene; in niso vedeli, kaj bi mu odgovorili.',
        41: 'In pride v tretje in jim reče: Spite dalje in počivajte! Dosti je! ura je prišla. Glej, Sin človekov se izdaja grešnikom v roke.',
        42: 'Vstanite, pojdimo! Glejte, izdajalec moj se je približal.',
        43: 'In precej, ko je še govoril, pride Juda, eden dvanajsterih, in ž njim množica z meči in koli od višjih duhovnikov in pismarjev in starejšin.',
        44: 'Dal jim je pa njegov izdajalec znamenje, rekoč: Kogar poljubim, ta je; zgrabite ga in peljite varno.',
        45: 'In pride in pristopi precej k njemu in reče: Rabi! in ga poljubi.',
        46: 'Oni pa polože nanj roke svoje in ga zgrabijo.',
        47: 'Eden tistih pa, ki so zraven stali, izdere meč in mahne hlapca velikega duhovnika in mu odseka uho.',
        48: 'In Jezus izpregovori in jim reče: Kakor na razbojnika ste prišli z meči in koli lovit me?',
        49: 'Vsak dan sem bil pri vas, učeč v templju, in niste me zgrabili. Ali da se izpolnijo pisma!',
        50: 'In zapuste ga vsi in pobegnejo.',
        51: 'In šel je za njim neki mladenič, s platnom ogrnjen po nagem, in ga popadejo.',
        52: 'On pa pusti platno in ubeži nag od njih.',
        53: 'In Jezusa odpeljejo k velikemu duhovniku; in snidejo se pri njem vsi višji duhovniki in starejšine in pismarji.',
        54: 'In Peter je šel oddaleč za njim, noter na dvor velikega duhovnika; in je sedel s hlapci, grejoč se pri ognju.',
        55: 'A višji duhovniki in ves veliki zbor so iskali pričevanja zoper Jezusa, da bi ga na smrt izdali; ali ne najdejo ga.',
        56: 'Kajti mnogi so pričali po krivem zoper njega, ali njih izpovedbe niso bile enake.',
        57: 'In vstanejo nekateri ter pričajo po krivem zoper njega, govoreč:',
        58: 'Mi smo ga slišali, da je dejal: Jaz poderem to svetišče, ki je narejeno z rokami, in v treh dneh sezidam drugo, ne narejeno z rokami.',
        59: 'Ali tudi to njih pričevanje ni bilo enako.',
        60: 'In veliki duhovnik vstane in stopi na sredo in vpraša Jezusa, rekoč: Ne odgovarjaš li ničesar? Kaj pričajo ti zoper tebe?',
        61: 'On pa je le molčal in ni odgovoril ničesar. Zopet ga vpraša veliki duhovnik in mu reče: Si li ti Kristus, Sin Veleslavnega?',
        62: 'Jezus pa reče: Jaz sem, in videli boste Sina človekovega, da sedi na desnici moči Božje in da prihaja z oblaki neba.',
        63: 'Veliki duhovnik pa raztrga oblačila svoja in reče: Kaj nam je še treba prič?',
        64: 'Slišali ste kletvino zoper Boga; kaj se vam zdi? Oni pa vsi razsodijo, da je vreden smrti.',
        65: 'In nekateri začno pljuvati nanj in mu zakrivati obraz in ga biti za uho in mu praviti: Prorokuj! Tudi služabniki so ga sprejeli z udarci po licih.',
        66: 'In ko je bil Peter doli na dvorišču, pride ena od dekel velikega duhovnika,',
        67: 'in videč Petra, da se greje, pogleda nanj in reče: Tudi ti si bil z Nazarečanom Jezusom.',
        68: 'On pa zataji, rekoč: Ne vem in ne umem, kaj praviš. In gre ven v preddvor, in petelin zapoje.',
        69: 'In dekla, videč ga, začne zopet praviti tem, ki so zraven stali: Ta je izmed njih.',
        70: 'On pa zopet taji. In malo potem reko zopet zraven stoječi Petru: Resnično si izmed njih, saj si tudi Galilejec.',
        71: 'On pa se začne rotiti in prisegati: Ne poznam tega človeka, ki o njem govorite.',
        72: 'In precej zapoje petelin drugič. In spomni se Peter besede, kako mu je rekel Jezus: Preden petelin dvakrat zapoje, me zatajiš trikrat. In ko to pomisli, se razplače.',
    },
    15: {
        1: 'In precej zjutraj se posvetujejo višji duhovniki s starejšinami in pismarji in ves veliki zbor, in zvežejo Jezusa, ga odpeljejo in izroče Pilatu.',
        2: 'In vpraša ga Pilat: Ti si kralj Judov? On pa odgovori in mu reče: Ti praviš.',
        3: 'In višji duhovniki so ga veliko tožili.',
        4: 'Pilat pa ga zopet vpraša, rekoč: Ne odgovarjaš li ničesar? Glej, kolikih reči te tožijo.',
        5: 'Ali Jezus mu ni nič več odgovoril, tako da se je Pilat čudil.',
        6: 'Ob prazniku pa jim je navadno izpustil enega jetnika, katerega so zahtevali.',
        7: 'Bil pa je takrat vklenjen v ječi eden, po imenu Baraba, z uporniki, ki so bili ob uporu uboj storili.',
        8: 'In ko pride množica gori, začne zahtevati, naj stori, kakor jim je vselej storil.',
        9: 'Pilat pa jim odgovori in reče: Hočete li, da vam izpustim kralja Judov?',
        10: 'Zaznal je namreč, da so mu ga iz zavisti izročili višji duhovniki.',
        11: 'Višji duhovniki pa podpihajo ljudstvo, naj jim rajši izpusti Baraba.',
        12: 'Pilat pa zopet odgovori in jim reče: Kaj torej hočete, da naj storim s tem, ki ga imenujete kralja Judov?',
        13: 'Oni pa zopet zakriče: Križaj ga!',
        14: 'Pilat jim pa reče: Kaj pa je hudega storil? Oni pa še bolj zakriče: Križaj ga!',
        15: 'Pilat pa, hoteč ljudstvu ustreči, jim izpusti Baraba, a Jezusa veli bičati in ga izroči, naj ga križajo.',
        16: 'In vojaki ga odpeljejo noter na dvor, to je v sodno palačo, in skličejo vso trumo.',
        17: 'In oblečejo mu škrlatno obleko in spleto krono iz trnja in jo denejo nanj,',
        18: 'in ga začno pozdravljati: Zdrav bodi, kralj Judov!',
        19: 'In bili so ga po glavi s trstom, in pljuvali so nanj, in pripogibali so kolena ter se mu priklanjali.',
        20: 'In ko se mu nasmejajo, mu slečejo škrlatno obleko in mu oblečejo lastno njegovo oblačilo; ter ga peljejo ven, da ga križajo.',
        21: 'In prisilijo nekega mimogredočega Simona Cirenca, ki je šel s polja, očeta Aleksandrovega in Rufovega, naj mu ponese križ.',
        22: 'In pripeljejo ga na kraj Golgoto, kar se tolmači: Mesto mrtvaške glave.',
        23: 'In podajali so mu vina z miro, ali on ni vzel.',
        24: 'In razpno ga na križ in delé med seboj obleko njegovo, metaje kocko zanjo, kdo bo kaj vzel.',
        25: 'Bila pa je ura tri, ko so ga na križ razpeli.',
        26: 'In bil je napis krivde njegove napisan: KRALJ JUDOV.',
        27: 'In ž njim križajo dva razbojnika, enega njemu na desno in enega na levo.',
        28: 'In izpolnilo se je pismo, ki pravi: „In hudodelnikom je bil prištet“.',
        29: 'In mimogredoči so ga preklinjali in majali z glavami in govorili: Aha, ki podiraš svetišče in ga v treh dneh postavljaš,',
        30: 'pomagaj sam sebi in stopi s križa!',
        31: 'Ravno tako so se mu tudi višji duhovniki posmehovali in govorili med seboj s pismarji: Drugim je pomagal, sam sebi ne more pomagati.',
        32: 'Kristus, kralj Izraelov, naj stopi sedaj s križa, da bomo videli in verovali. Tudi ona, ki sta bila križana ž njim, sta ga zasramovala.',
        33: 'In ko je bila ura šest, nastane tema po vsej zemlji do devete ure.',
        34: 'In ob deveti uri zavpije Jezus z močnim glasom: Eloi, Eloi, lama sabahtani? kar se tolmači: „Bog moj, Bog moj, zakaj si me zapustil?“',
        35: 'In nekateri tistih, ki so zraven stali in slišali to, reko: Glej, Elija kliče.',
        36: 'Eden pa pohiti in namoči gobo z octom in, nateknivši jo na trst, mu da piti, rekoč: Pustite, bomo videli, če pride Elija, da ga sname.',
        37: 'Jezus pa zavpije z močnim glasom in izdahne.',
        38: 'In zagrinjalo v svetišču se pretrga na dvoje, od vrha do tal.',
        39: 'Ko je pa stotnik, ki je stal njemu nasproti, videl, da je tako zakričavši izdahnil, reče: Resnično je bil ta človek Sin Božji.',
        40: 'Bile pa so tu tudi žene, ki so oddaleč gledale, med katerimi je bila Marija Magdalena in Marija, Jakoba manjšega in Jozejeva mati, in Salome,',
        41: 'ki so, ko je bil še v Galileji, za njim hodile in mu služile, in mnoge druge, katere so bile ž njim prišle v Jeruzalem.',
        42: 'In ko se je že zvečerilo, ker je bil dan priprave, to se pravi: predsobotni dan,',
        43: 'pride Jožef iz Arimateje, velespoštovan svetovalec, ki je tudi pričakoval kraljestva Božjega, in gre srčno k Pilatu in zaprosi Jezusovo truplo.',
        44: 'Pilat se pa začudi, da je že umrl, in pokliče stotnika ter ga vpraša, je li že kaj časa mrtev.',
        45: 'In ko zve od stotnika, podari truplo Jožefu.',
        46: 'In kupivši platna, ga sname in ga zavije v platno in položi v grob, ki je bil izsekan v skali; in privali kamen grobu na vrata.',
        47: 'Marija Magdalena in Marija, mati Jozejeva, pa sta gledali, kam je bil položen.',
    },
    16: {
        1: 'In ko mine sobota, nakupijo Marija Magdalena in Marija, mati Jakobova, in Salome dišav, da bi prišle in ga pomazilile.',
        2: 'In zjutraj zgodaj prvi dan po soboti pridejo h grobu, ko je solnce izšlo.',
        3: 'In pogovarjale so se med seboj: Kdo nam odvali kamen od grobnih vrat?',
        4: 'In ko pogledajo, vidijo, da je kamen odvaljen; bil je namreč zelo velik.',
        5: 'In prišedši v grob, ugledajo mladeniča, da sedi na desni strani in je ogrnjen z belim oblačilom; in prestrašijo se.',
        6: 'On jim pa reče: Ne bojte se! Jezusa iščete Nazarečana, ki je bil križan; vstal je, ni ga tu. Glejte mesto, kamor so ga bili položili.',
        7: 'Ali pojdite, povejte učencem njegovim in Petru, da gre pred vami v Galilejo; tam ga boste videli, kakor vam je rekel.',
        8: 'In pridejo iz groba in naglo zbeže; zakaj strah in groza sta jih prevzela, in nikomur niso ničesar povedale, ker so se bale. —',
        9: 'Vstavši pa zgodaj prvi dan po soboti, se prikaže Jezus najprej Mariji Magdaleni, iz katere je bil izgnal sedem hudičev.',
        10: 'Ona odide in sporoči tem, ki so prej bili ž njim, ki so žalovali in jokali.',
        11: 'In ko slišijo, da živi in da ga je ona videla, niso verovali.',
        12: 'Potem se razodene v drugi podobi dvema izmed njih na poti, ko sta šla na deželo.',
        13: 'In ona odideta in oznanita drugim, ali tudi njima niso verovali.',
        14: 'Pozneje se razodene enajsterim, ko so sedeli za mizo, in pograja njih nevero in trdosrčost, da niso verjeli tem, ki so ga videli, da je vstal.',
        15: 'In jim reče: Pojdite po vsem svetu in oznanite evangelij vsemu stvarjenju!',
        16: 'Kdor veruje in je krščen, bo zveličan, a kdor ne veruje, bo obsojen.',
        17: 'Tiste pa, ki verujejo, bodo spremljala ta znamenja: V imenu mojem bodo izganjali zle duhove, govorili bodo nove jezike,',
        18: 'kače bodo prijemali, in če izpijo kaj strupenega, ne bo jim škodovalo, na bolnike bodo pokladali roke, in ozdravijo.',
        19: 'In Gospod, potem ko jim je govoril, je bil vzet gori v nebo, in je sedel Bogu na desnici.',
        20: 'Oni pa so šli in oznanjevali so povsodi, in Gospod je sodeloval ž njimi in potrjeval besedo s čudeži, ki so se obenem godili.',
    },
}
